  async function sync(silent=false){if(syncRunning){syncQueued=true;return false}if(!navigator.onLine){scheduleRetry();return false}const syncButton=$('#syncBtn'),ownsButton=Boolean(syncButton&&syncButton.dataset.busy!=='true');if(ownsButton){syncButton.disabled=true;syncButton.classList.add('isSyncing');setSyncButtonText('☁ SINCRONIZANDO')}syncRunning=true;clearTimeout(retryTimer);try{$('#syncStatus').textContent='Sincronizando…';updatePendingBadge('syncing');await syncPendingCollaborators();const result=await post({action:'plazaSync',token,since:localStorage.getItem('skPlazaServerUpdatedAt')||'',data:{assets:(data.assets||[]).filter(row=>row.syncState==='pending'),blendingIncomes:(data.blendingIncomes||[]).filter(row=>row.syncState==='pending'),blendingDeliveries:(data.blendingDeliveries||[]).filter(row=>row.syncState==='pending')}}),syncedAt=new Date().toISOString();if(result.updatedAt)localStorage.setItem('skPlazaServerUpdatedAt',result.updatedAt);localStorage.setItem('skPlazaLastSync',syncedAt);retryAttempts=0;if(result.notModified){updatePendingBadge();showLastSync(syncedAt);$('#syncStatus').textContent=`Sincronizado · sin cambios · ${new Date().toLocaleString('es-CO')}`;return true}const incoming=result.data&&typeof result.data==='object'?result.data:{},previous=data&&typeof data==='object'?data:{},aliases={personal:['personal','people','personnel'],inventoryCriteria:['inventoryCriteria','criteria','criteriosInventario'],inventoryStock:['inventoryStock','stock','existencias'],assets:['assets','fixedAssets','activosFijos']};for(const [key,names] of Object.entries(aliases)){if(!Array.isArray(incoming[key])){const found=names.map(name=>incoming[name]).find(Array.isArray);if(found)incoming[key]=found}if((!Array.isArray(incoming[key])||incoming[key].length===0)&&Array.isArray(previous[key])&&previous[key].length)incoming[key]=previous[key]}data={...previous,...incoming};localStorage.setItem('skPlazaData',JSON.stringify(data));if(incoming.updatedAt)localStorage.setItem('skPlazaServerUpdatedAt',incoming.updatedAt);render();showLastSync(syncedAt);$('#syncStatus').textContent=`Sincronizado · ${new Date().toLocaleString('es-CO')}`;return true}catch(error){if(/sesión venció|sesión no válida/i.test(error.message)){if(silent){$('#syncStatus').textContent='Sesión pendiente de validar · reintentando automáticamente';scheduleRetry();return false}logout();return false}scheduleRetry();if(!silent)alert('Los datos permanecen guardados en este dispositivo. La aplicación reintentará la sincronización automáticamente.');return false}finally{syncRunning=false;if(ownsButton){syncButton.disabled=false;syncButton.classList.remove('isSyncing');syncButton.textContent='☁ SINCRONIZAR'}if(syncQueued){syncQueued=false;setTimeout(()=>sync(true),0)}}}
  async function syncDataAndApp(){const button=$('#syncBtn');if(button?.dataset.busy==='true')return;if(button){button.dataset.busy='true';button.disabled=true;button.classList.add('isSyncing');setSyncButtonText('☁ SINCRONIZANDO')}let dataOk=false,appOk=false;try{dataOk=await sync(false);if(button)setSyncButtonText('↻ ACTUALIZANDO APP');if(window.SKPlazaInstall?.updateApp){await window.SKPlazaInstall.updateApp();appOk=true}else appOk=true;if(dataOk&&appOk){$('#syncStatus').textContent=`Datos y aplicación actualizados · ${new Date().toLocaleString('es-CO')}`;updatePendingBadge()}}catch(error){console.error('Actualización de Plaza:',error);if(dataOk)alert('Los datos se sincronizaron, pero la aplicación no pudo comprobar actualizaciones. Se intentará nuevamente al abrirla.')}finally{if(button){button.dataset.busy='false';button.disabled=false;button.classList.remove('isSyncing');setSyncButtonText('☁ SINCRONIZAR')}}}
